    public static void testCentipointsPrintAsPoints() {
        StringBuilder t = emon.Testport.newText();
        Json.jsCpt(t, 7250);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 7200);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, -5);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 0);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 12);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 10);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 5);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 99);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 100);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 101);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 1234);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, -150);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, -100);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, -2147483648);
        emon.Port.textAscii(t, " ");
        Json.jsCpt(t, 2147483647);
        emon.Testport.assertText(t, "72.5 72 -0.05 0 0.12 0.1 0.05 0.99 1 1.01 12.34 -1.5 -1 -21474836.48 21474836.47", "points");
    }
